import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.Boholvbs.js";const m=JSON.parse('{"title":"Calls (removed in 0.1.22)","description":"","frontmatter":{},"headers":[],"relativePath":"calls.md","filePath":"calls.md"}'),s={name:"calls.md"};function r(i,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="calls-removed-in-0-1-22" tabindex="-1">Calls (removed in 0.1.22) <a class="header-anchor" href="#calls-removed-in-0-1-22" aria-label="Permalink to &quot;Calls (removed in 0.1.22)&quot;">​</a></h1><p>Versions 0.1.20 and 0.1.21 could place a voice or video call with the agent through Qwen Omni&#39;s real-time socket. It was expensive to run for everyone and out of the project&#39;s way — a personal agent that <em>does things</em> — so 0.1.22 took it out of every app and the relay. Older ledger rows of kind <code>realtime</code> and messages marked &quot;said on a call&quot; still display.</p><p>What remains is voice <strong>input</strong>: on the phone the microphone button in the composer (the system&#39;s or a provider&#39;s speech recognition, as in OpenMinis); in nanoMuse Web and the desktop app a microphone button next to <em>Send</em> that uses the browser&#39;s own speech recognition where it exists (Chrome, Edge, Safari) — nothing is sent anywhere by nanoMuse, no model is involved, and the words land in the box for you to send.</p><p>The design and the code of the calls live in the history of the repository (<code>git show v0.1.21:docs/calls.md</code>).</p>',4)])])}const u=o(s,[["render",r]]);export{m as __pageData,u as default};
